<?php
$title='Appointments';$subtitle='Meetings booked by leads or your team';
$me=user();$sales=role()==='sales';
$au=$sales?' AND (a.user_id='.(int)$me['id'].' OR l.assigned_to='.(int)$me['id'].' OR l.assigned_to IS NULL)':'';
if(is_post()){
  $a=$_POST['a']??'';
  try{
    if($a==='add'){
      $t=strtotime($_POST['at']??'');if(!$t)throw new Exception('Pick a date and time.');
      $lid=(int)($_POST['lead']??0);
      if($lid&&!lead_ok(DB::row('SELECT * FROM leads WHERE id=?',[$lid])))throw new Exception('Choose one of your leads.');
      if(!$lid){$n=trim($_POST['name']??'');if($n==='')throw new Exception('Choose a lead or enter a name.');$lid=CRM::create(['contact_name'=>$n,'name'=>trim($_POST['company']??'')?:$n,'phone'=>trim($_POST['phone']??''),'email'=>trim($_POST['email']??'')],'manual','Appointment');if($sales)DB::update('leads',['assigned_to'=>$me['id']],'id=?',[$lid]);}
      Booking::book($lid,$t,'admin',trim($_POST['notes']??''),trim($_POST['title']??'')?:null);flash('Appointment booked'.(GCal::ready()?' and added to Google Calendar':'').'.');}
    if($a==='st'&&DB::val("SELECT a.id FROM appointments a LEFT JOIN leads l ON l.id=a.lead_id WHERE a.id=?$au",[(int)$_POST['id']]))Booking::status((int)$_POST['id'],$_POST['st']??'');
  }catch(Throwable $e){flash(e($e->getMessage()),'err');}
  back(url('appointments'));}
$m=preg_match('/^\d{4}-\d{2}$/',$_GET['m']??'')?$_GET['m']:date('Y-m');
$first=strtotime($m.'-01');$start=strtotime('monday this week',$first);if(date('N',$first)==1)$start=$first;
$end=strtotime('+41 days',$start);
$rows=DB::all("SELECT a.*,l.name,l.contact_name FROM appointments a LEFT JOIN leads l ON l.id=a.lead_id WHERE a.start_at BETWEEN ? AND ?$au ORDER BY a.start_at",[date('Y-m-d 00:00:00',$start),date('Y-m-d 23:59:59',$end)]);
$by=[];foreach($rows as $r)$by[substr($r['start_at'],0,10)][]=$r;
$up=DB::all("SELECT a.*,l.name,l.contact_name,l.phone FROM appointments a LEFT JOIN leads l ON l.id=a.lead_id WHERE a.status='scheduled' AND a.start_at>=NOW()-INTERVAL 1 HOUR$au ORDER BY a.start_at LIMIT 10");
$leads=DB::all('SELECT l.id,l.name,l.contact_name FROM leads l WHERE l.is_lead=1'.scope().' ORDER BY COALESCE(l.lead_at,l.created_at) DESC LIMIT 400');
$k=DB::row("SELECT SUM(a.status='scheduled' AND a.start_at>=NOW()) up,SUM(DATE(a.start_at)=CURDATE() AND a.status='scheduled') td,SUM(a.status='completed') dn,SUM(a.status='no_show') ns,SUM(a.booked_by='lead') sb FROM appointments a LEFT JOIN leads l ON l.id=a.lead_id WHERE 1=1$au");
$pre=(int)($_GET['lead']??0);
?>
<div class="stats"><?=kpi('Upcoming',(int)$k['up'],'cal','teal',(int)$k['td'].' today')?><?=kpi('Completed',(int)$k['dn'],'check','green','meetings held')?><?=kpi('No-shows',(int)$k['ns'],'alert','orange','follow up again')?><?=kpi('Self-booked',(int)$k['sb'],'link','violet','via your booking link')?></div>
<div class="g3"><div class="col">
<form method="post" class="card" id="book"><?=csrf_field()?><input type="hidden" name="a" value="add"><div class="card-h"><h3><span class="hi c-teal"><?=icon('plus')?></span>Book a meeting</h3><?php if(GCal::ready()):?><span class="bdg c-green bdg-dot">Google Calendar</span><?php endif?></div><label>Lead<select name="lead" data-toggle><option value="">— New person —</option><?php foreach($leads as $x):?><option value="<?=$x['id']?>" <?=$pre===(int)$x['id']?'selected':''?>><?=e($x['contact_name']?:$x['name'])?></option><?php endforeach?></select></label><div class="fg" data-show="lead="><label>Name<input name="name"></label><label>Phone<input name="phone" type="tel"></label><label>Email<input name="email" type="email"></label><label>Business<input name="company"></label></div><label>Date &amp; time<input type="datetime-local" name="at" required min="<?=date('Y-m-d\TH:i')?>"></label><label>Title<input name="title" placeholder="<?=e(setting('appt_title','Meeting'))?>"></label><label class="mb0">Notes<textarea name="notes" rows="2"></textarea></label><div class="card-f"><button class="btn btn-p"><?=icon('check')?>Book meeting</button><span class="muted xs"><?=(int)setting('appt_slot','30')?> min · confirmation sent by email</span></div></form>
<div class="card"><div class="card-h"><h3><span class="hi c-violet"><?=icon('link')?></span>Let leads book themselves</h3></div><p class="sm muted">Share your booking page. Free slots follow your working hours<?=GCal::ready()?' and your Google Calendar':''?>. Each lead also has a personal link – use <code>{{booking_link}}</code> in messages.</p><div class="copy"><input readonly value="<?=e(Booking::link())?>"><button type="button" class="btn btn-sm" data-copy="<?=e(Booking::link())?>"><?=icon('copy')?></button><a class="btn btn-sm" href="<?=e(Booking::link())?>" target="_blank" title="Preview"><?=icon('eye')?></a></div><?php if(can('settings')):?><p class="hint">Hours, slot length, reminders &amp; Google Calendar: <a class="lnk" href="<?=url('settings',['tab'=>'appointments'])?>">Settings → Appointments</a></p><?php endif?></div>
<div class="card"><div class="card-h"><h3><span class="hi c-teal"><?=icon('clock')?></span>Next up</h3></div><?php if(!$up):?><div class="empty sm"><?=icon('cal')?><p>No upcoming appointments.</p></div><?php endif?><?php foreach($up as $a):?><div class="li"><span class="when c-teal"><b><?=date('d',strtotime($a['start_at']))?></b><small><?=date('M',strtotime($a['start_at']))?></small></span><div class="grow"><b><a href="<?=url('lead',['id'=>$a['lead_id']])?>"><?=e($a['contact_name']?:$a['name'])?></a></b><small><?=e(date('D h:i A',strtotime($a['start_at'])))?><?=$a['phone']?' · '.e($a['phone']):''?></small><form method="post" class="row" style="gap:4px;margin-top:6px"><?=csrf_field()?><input type="hidden" name="a" value="st"><input type="hidden" name="id" value="<?=$a['id']?>"><?php if($a['meet_link']):?><a class="btn btn-xs btn-g" href="<?=e($a['meet_link'])?>" target="_blank" rel="noopener"><?=icon('play')?>Join</a><?php endif?><button class="btn btn-xs" name="st" value="completed"><?=icon('check')?>Done</button><button class="btn btn-xs" name="st" value="no_show">No-show</button><button class="btn btn-xs" name="st" value="cancelled" onclick="return confirm('Cancel this appointment?')">Cancel</button></form></div></div><?php endforeach?></div></div>
<div class="col"><div class="card"><div class="card-h"><h3><span class="hi c-indigo"><?=icon('cal')?></span><?=e(date('F Y',$first))?></h3><div class="row"><a class="ib bd" href="<?=url('appointments',['m'=>date('Y-m',strtotime('-1 month',$first))])?>" title="Previous month">‹</a><a class="btn btn-sm" href="<?=url('appointments')?>">Today</a><a class="ib bd" href="<?=url('appointments',['m'=>date('Y-m',strtotime('+1 month',$first))])?>" title="Next month">›</a></div></div><div class="cal"><?php foreach(['Mon','Tue','Wed','Thu','Fri','Sat','Sun'] as $dn):?><div class="ch"><?=$dn?></div><?php endforeach?><?php for($d=$start;$d<=$end;$d=strtotime('+1 day',$d)):$ds=date('Y-m-d',$d);?><div class="<?=date('Y-m',$d)!==$m?'out':''?> <?=$ds===date('Y-m-d')?'td':''?>"><span class="dn"><?=date('j',$d)?></span><?php foreach($by[$ds]??[] as $a):?><a class="ev <?=$a['status']==='completed'?'done':(in_array($a['status'],['cancelled','no_show'],true)?'cx':'')?>" href="<?=url('lead',['id'=>$a['lead_id']])?>" title="<?=e($a['title'])?>"><?=date('H:i',strtotime($a['start_at']))?> <?=e($a['contact_name']?:$a['name'])?></a><?php endforeach?></div><?php endfor?></div></div></div></div>
<?php if(isset($_GET['add'])):?><script>addEventListener('load',function(){var f=document.querySelector('#book [name=at]');f.scrollIntoView({block:'center'});f.focus()})</script><?php endif?>
